async function oatCall(action,data={}){const r=await fetch('/api/acceptance/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function oatLoad(){const d=await oatCall('status');document.getElementById('oat-records').innerHTML=`<h2>Production promotion blocked</h2><ul>${d.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><h2>Capability status</h2>${Object.entries(d.capabilities).map(([k,v])=>`<article class="callout"><h3>${esc(k)}</h3><p>${esc(v)}</p></article>`).join('')}<h2>Acceptance scorecard</h2>${d.areas.map(a=>`<p><strong>${esc(a.name)}</strong>: ${esc(a.status)}</p>`).join('')}<h2>Submitted evidence — unverified</h2>${d.evidence.map(e=>`<article class="callout"><h3>${esc(e.area)} · ${esc(e.release)}</h3><p>Owner: ${esc(e.owner)}</p><p>${esc(e.reference)}</p><p>${esc(e.note)}</p></article>`).join('')||'<p>No evidence submitted.</p>'}`;document.querySelector('#oat-submit select').innerHTML=d.areas.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');}
const beforeOat=render;render=function(){if(location.hash==='#operational-acceptance'){document.getElementById('app').innerHTML=integratedShell('operational-acceptance',heading('Operational acceptance','Local evidence register · Production not approved')+`<section class="card prose"><p id="oat-status" role="status"></p><div id="oat-records"></div></section><section class="card prose"><h2>Submit evidence for review</h2><p>Submitting a reference does not verify it or pass an acceptance gate.</p><form id="oat-submit"><label>Area<select name="area" required><option value="">Connect first</option></select></label><label>Release<input name="release" maxlength="120" required></label><label>Evidence owner<input name="owner" maxlength="120" required></label><label>Evidence reference<input name="reference" maxlength="1000" required></label><label>Findings<textarea name="note" maxlength="2000" required></textarea></label><button class="button">Record evidence</button></form></section>`,model.role);bind();if(governedToken)oatLoad().catch(e=>document.getElementById('oat-status').textContent=e.message);}else beforeOat();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#operational-acceptance"]'))nav.insertAdjacentHTML('beforeend','<a href="#operational-acceptance">Operational acceptance</a>');};
document.addEventListener('submit',async e=>{if(!['oat-connect','oat-submit'].includes(e.target.id))return;e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(e.target.id==='oat-connect'){governedToken=d.token;e.target.reset();}else await oatCall('record',d);await oatLoad();document.getElementById('oat-status').textContent='Loaded. Evidence requires independent verification.';}catch(err){document.getElementById('oat-status').textContent=err.message;}});render();
